select count(distinct v.id)
from videos v
left join categories c on v.category_id = c.id

     and v.title like concat('%', #{title}, '%')
     and v.subtitle like concat('%', #{subtitle}, '%')
     and v.author like concat('%', #{author}, '%')

        and (v.category_id = #{categoryId}
        or exists (
            select 1 from video_category_tag_relations vctr
            where vctr.video_id = v.id and vctr.relation_type = 1 and vctr.category_id = #{categoryId}
        ))

     and v.status = #{status}
     and v.is_recommended = #{isRecommended}
     and v.is_hot = #{isHot}

    and NOT exists (
        select 1 
        from video_category_tag_relations vctr 
