select v.id, v.title, v.subtitle, v.description, v.video_content, v.cover_image, v.duration, v.file_size, v.author, v.category_id, v.sort_order, v.is_recommended, v.is_hot, v.status, v.published_at, v.last_edited_at, v.created_at, v.updated_at, v.transcode_id, v.md5, v.shareid, v.orgfile, v.rpath, v.domain, v.path, v.suffix, v.resolution, v.bitrate, v.fps, v.width, v.height, v.transcode_status, v.thumbnails, v.output_formats, v.slug, v.meta_title, v.meta_description, v.meta_keywords, v.video_type, v.quality, v.is_featured, v.allow_comments, v.language, -- 优先显示关联表中的分类，其次是直接关联的分类 COALESCE( (select GROUP_CONCAT(c2.name ORDER BY c2.sort_order DESC SEPARATOR ', ') from video_category_tag_relations vctr2 inner join categories c2 on vctr2.category_id = c2.id and c2.status = 1 where vctr2.video_id = v.id and vctr2.relation_type = 1), c.name ) as category_name, (select count(*) from video_images vi where vi.video_id = v.id and vi.status = 1) as image_count, (select count(*) from video_urls vu where vu.video_id = v.id and vu.status = 1) as url_count, -- 关联统计数据 COALESCE(vs.view_count, 0) as stats_view_count, COALESCE(vs.play_count, 0) as stats_play_count, COALESCE(vs.like_count, 0) as stats_like_count, COALESCE(vs.comment_count, 0) as stats_comment_count, COALESCE(vs.share_count, 0) as stats_share_count from videos v left join categories c on v.category_id = c.id left join video_statistics vs on v.id = vs.video_id
and v.title like concat('%', #{title}, '%') and v.subtitle like concat('%', #{subtitle}, '%') and v.author like concat('%', #{author}, '%')
