and date_format(v.created_at,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')
and date_format(v.published_at,'%y%m%d') >= date_format(#{params.publishBeginTime},'%y%m%d')
and date_format(v.published_at,'%y%m%d') <= date_format(#{params.publishEndTime},'%y%m%d')
and (v.category_id in
#{categoryId}
