SELECT vctr.video_id as videoId, t.id as tagId, t.name as tagName, t.color as tagColor, t.is_hot as isHot FROM video_category_tag_relations vctr INNER JOIN tags t ON vctr.tag_id = t.id AND t.status = 1 WHERE vctr.video_id IN
#{videoId}
AND vctr.relation_type = 2 ORDER BY vctr.video_id, t.id DESC

